import React, { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { FaHouse, FaChartBar, FaGlobe, FaYoutube, FaUsers } from 'react-icons/fa6';

import { Box, Center, HStack, Stack, styled } from 'styled-system/jsx';
import { BottomNavigation } from '~/components/layout/BottomNavigation';
import { LanguageToggle } from '~/components/layout/LanguageToggle';
import { NavigationItems } from '~/components/layout/NavigationItems';

export default function Layout({ children }: { children: React.ReactNode }) {
  const [currentPath, setCurrentPath] = useState(import.meta.env.BASE_URL);
  const { t } = useTranslation();

  const pathPrefix = import.meta.env.DEV ? '/static' : '/';

  const navigationItems = [
    { href: pathPrefix, icon: FaHouse, labelKey: 'navigation.home' },
    { href: `${pathPrefix}/members`, icon: FaUsers, labelKey: 'navigation.members' },
    {
      href: `${pathPrefix}/summary`,
      icon: FaChartBar,
      labelKey: 'navigation.summary'
    },
    {
      href: 'https://www.lovelive-anime.jp/lovehigh/',
      icon: FaGlobe,
      labelKey: 'navigation.homepage',
      isExternal: true
    },
    {
      href: 'https://www.youtube.com/@IKIZULIVE/',
      icon: FaYoutube,
      labelKey: 'navigation.youtube',
      isExternal: true
    }
  ];

  useEffect(() => {
    setCurrentPath(window.location.pathname);
  }, [children]);

  return (
    <HStack display="flex" gap="0" alignItems="flex-start" w="full">
      {/* Left Sidebar */}

      <Box
        display={{ base: 'none', md: 'flex' }} // Hide on small screens
        position="sticky"
        top="0"
        justifyContent="flex-end"
        w={{ base: 'auto', lg: 'full' }}
        bg="bg.default"
      >
        <Stack
          display="flex"
          gap="6" // Increased gap for more vertical spacing
          alignItems="flex-start" // Ensure items are left-aligned
          borderRight="1px solid"
          borderRightColor="border.default"
          w="full"
          maxW={{ base: 'auto', lg: '250px' }}
          h="screen"
          p="4"
        >
          <Box w="12" h="12">
            <styled.img
              src="https://www.lovelive-anime.jp/lovehigh/img/koushou.png"
              alt={t('bluebird.sidebar.posterAlt')}
              objectFit="contain"
              w="full"
              h="full"
            />
          </Box>
          <NavigationItems items={navigationItems} currentPath={currentPath} />
          <Center w="full">
            <LanguageToggle />
          </Center>
        </Stack>
      </Box>
      {children}
      <BottomNavigation items={navigationItems} currentPath={currentPath} />
    </HStack>
  );
}
